<script setup lang="ts">
import { ref } from 'vue'
import { ArrowRight, Download, ImageDown, Smartphone } from '@lucide/vue'
import { useAppStore } from '@/stores/app-store'
import { saveWechatQrCode } from '@/infrastructure/files/wechat-qr-service'
import wechatQr from '@/assets/wechat-qr.png'
import brandMark from '@/assets/brand-mark.svg'

const store = useAppStore()
const appVersion = import.meta.env.VITE_APP_VERSION ?? '1.0.4'
const contactSaveState = ref<'idle' | 'done' | 'error'>('idle')

async function saveContactQrCode(): Promise<void> {
  contactSaveState.value = 'idle'
  try {
    await saveWechatQrCode(wechatQr)
    contactSaveState.value = 'done'
    setTimeout(() => { contactSaveState.value = 'idle' }, 2500)
  } catch {
    contactSaveState.value = 'error'
  }
}
</script>

<template>
  <!-- 平铺布局（无卡片分组）：品牌区居中 → 分隔线小标题「开发者微信」→ 二维码 + 扫码教程 + 保存按钮 -->
  <main class="page about-page">
    <div class="brand">
      <span class="logo"><img :src="brandMark" alt="抽屉账本 Logo" /></span>
      <h2>抽屉账本</h2>
      <p class="slogan">一个安安静静记账的小工具。<br />无需注册，没有广告；记下日常收支，看清钱花在哪里。<br />账单默认留在本机，激活后可离线记账，也能自行备份。<br />一次买断，授权永久有效。</p>
      <span class="version">v{{ appVersion }}</span>
    </div>

    <div class="divider" role="separator">开发者微信</div>

    <div class="contact">
      <div class="qr-frame">
        <img :src="wechatQr" alt="开发者的微信二维码" class="contact-qr" />
      </div>
      <div class="contact-flow" aria-label="扫码加好友步骤">
        <div class="contact-step">
          <span class="contact-step-icon" aria-hidden="true"><ImageDown :size="20" /></span>
          <span>保存图片<br />到相册</span>
        </div>
        <ArrowRight class="contact-arrow" :size="22" aria-hidden="true" />
        <div class="contact-step">
          <span class="contact-step-icon" aria-hidden="true"><Smartphone :size="20" /></span>
          <span>打开微信<br />扫一扫</span>
        </div>
      </div>
      <button class="button secondary contact-save" type="button" @click="saveContactQrCode">
        <Download :size="18" />{{ contactSaveState === 'done' ? '已保存' : contactSaveState === 'error' ? '保存失败，重试' : '保存二维码' }}
      </button>
    </div>
  </main>
</template>

